MOTIF_NAME = 'stone_count_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones on the board than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_count = 0
    opp_count = 0
    for row in board_rows:
        for stone in row:
            if stone == color:
                color_count += 1
            elif stone == opp:
                opp_count += 1
    return color_count > opp_count

MOTIF_NAME = 'unpressed_diagonal_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones with at least one diagonal empty point not blocked by opponent noses, indicating uncrowded shape.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_score = 0
    opp_score = 0

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.':
                continue

            has_unpressed = False

            # Check Top-Left diagonal (r-1, c-1)
            if r > 0 and c > 0:
                if board_rows[r-1][c-1] == '.':
                    if not (board_rows[r-1][c] == opp and board_rows[r][c-1] == opp):
                        has_unpressed = True

            # Check Top-Right diagonal (r-1, c+1)
            if not has_unpressed and r > 0 and c < 18:
                if board_rows[r-1][c+1] == '.':
                    if not (board_rows[r-1][c] == opp and board_rows[r][c+1] == opp):
                        has_unpressed = True

            # Check Bottom-Left diagonal (r+1, c-1)
            if not has_unpressed and r < 18 and c > 0:
                if board_rows[r+1][c-1] == '.':
                    if not (board_rows[r+1][c] == opp and board_rows[r][c-1] == opp):
                        has_unpressed = True

            # Check Bottom-Right diagonal (r+1, c+1)
            if not has_unpressed and r < 18 and c < 18:
                if board_rows[r+1][c+1] == '.':
                    if not (board_rows[r+1][c] == opp and board_rows[r][c+1] == opp):
                        has_unpressed = True

            if has_unpressed:
                if stone == color:
                    color_score += 1
                else:
                    opp_score += 1

    return color_score > opp_score

