                if board_rows[r+1][c-1] == '.' and board_rows[r+2][c-2] == '.':
                    has_open_quarter = True
            # Bottom-right quadrant
            if not has_open_quarter and r < 17 and c < 17:
                if board_rows[r+1][c+1] == '.' and board_rows[r+2][c+2] == '.':
                    has_open_quarter = True

