MOTIF_NAME = 'corner_territory_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones in the four corner regions (6x6 each) than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_corner = 0
    opp_corner = 0
    corners = [(0, 0), (0, 13), (13, 0), (13, 13)]
    checked = set()
    for sr, sc in corners:
        for dr in range(6):
            for dc in range(6):
                r, c = sr + dr, sc + dc
                if 0 <= r < 19 and 0 <= c < 19:
                    if (r, c) not in checked:
                        checked.add((r, c))
                        stone = board_rows[r][c]
                        if stone == color:
                            color_corner += 1
                        elif stone == opp:
                            opp_corner += 1
    return color_corner > opp_corner

MOTIF_NAME = 'framework_base_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones on the 3rd-4th lines with empty space toward center and same-color support toward the edge, indicating good framework bases.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_bases = 0
    opp_bases = 0

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.':
                continue

            is_framework_line = (r == 2 or r == 3 or r == 15 or r == 16 or c == 2 or c == 3 or c == 15 or c == 16)
            if not is_framework_line:
                continue

            has_center_empty = False
            has_edge_support = False

            # Top edge (rows 2-3), check below for empty, above for support
            if r == 2 or r == 3:
                if r + 1 < 19 and board_rows[r + 1][c] == '.':
                    has_center_empty = True
                if r - 1 >= 0 and board_rows[r - 1][c] == stone:
                    has_edge_support = True

            # Bottom edge (rows 15-16), check above for empty, below for support
            if r == 15 or r == 16:
                if r - 1 >= 0 and board_rows[r - 1][c] == '.':
                    has_center_empty = True
                if r + 1 < 19 and board_rows[r + 1][c] == stone:
                    has_edge_support = True

            # Left edge (cols 2-3), check right for empty, left for support
            if c == 2 or c == 3:
                if c + 1 < 19 and board_rows[r][c + 1] == '.':
                    has_center_empty = True
                if c - 1 >= 0 and board_rows[r][c - 1] == stone:
                    has_edge_support = True

            # Right edge (cols 15-16), check left for empty, right for support
            if c == 15 or c == 16:
                if c - 1 >= 0 and board_rows[r][c - 1] == '.':
                    has_center_empty = True
                if c + 1 < 19 and board_rows[r][c + 1] == stone:
                    has_edge_support = True

            if has_center_empty and has_edge_support:
                if stone == color:
                    color_bases += 1
                else:
                    opp_bases += 1

    return color_bases > opp_bases

MOTIF_NAME = 'cutting_point_potential_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more empty points adjacent to both colors where placing a stone would cut between opponent groups, indicating fighting advantage.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_cuts = 0
    opp_cuts = 0

    for r in range(19):
        for c in range(19):
            if board_rows[r][c] != '.':
                continue

            adj_color = set()
            adj_opp = set()

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    neighbor = board_rows[nr][nc]
                    if neighbor == color:
                        adj_color.add((nr, nc))
                    elif neighbor == opp:
                        adj_opp.add((nr, nc))

            if len(adj_color) >= 1 and len(adj_opp) >= 1:
                color_diag = 0
                opp_diag = 0
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        if board_rows[nr][nc] == color:
                            color_diag += 1
                        elif board_rows[nr][nc] == opp:
                            opp_diag += 1

                if color_diag >= 1 and opp_diag == 0:
                    color_cuts += 1
                elif opp_diag >= 1 and color_diag == 0:
                    opp_cuts += 1

    return color_cuts > opp_cuts

