MOTIF_NAME = 'adjacent_empty_advantage'
MOTIF_DESCRIPTION = 'The evaluated color stones are adjacent to more unique empty points than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_libs = set()
    opp_libs = set()
    for r, row in enumerate(board_rows):
        for c, stone in enumerate(row):
            if stone == '.': continue
            target_set = color_libs if stone == color else opp_libs
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    if board_rows[nr][nc] == '.':
                        target_set.add((nr,nc))
