MOTIF_NAME = 'group_vitality_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones in groups with 5 or more unique liberties, indicating groups with strong life potential and fighting strength.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'

    visited = [[False]*19 for _ in range(19)]
    color_vital = 0
    opp_vital = 0

    def get_group_and_liberties(start_r, start_c, stone_color):
        group = []
        liberties = set()
        stack = [(start_r, start_c)]
        visited[start_r][start_c] = True

        while stack:
            r, c = stack.pop()
            group.append((r, c))

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    neighbor = board_rows[nr][nc]
                    if neighbor == '.':
                        liberties.add((nr, nc))
                    elif neighbor == stone_color and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))

        return group, liberties

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.' or visited[r][c]:
                continue

            group, liberties = get_group_and_liberties(r, c, stone)

            if len(liberties) >= 5:
                if stone == color:
                    color_vital += len(group)
                else:
                    opp_vital += len(group)

    return color_vital > opp_vital

