MOTIF_NAME = 'expansion_potential_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones on lines 2-6 with empty space toward the board center, indicating good expansion potential.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_expansion = 0
    opp_expansion = 0

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.':
                continue

            # Check if stone is on lines 2-6 from any edge (territory/influence zone)
            on_territory_line = (1 <= r <= 5 or 13 <= r <= 17 or 1 <= c <= 5 or 13 <= c <= 17)
            if not on_territory_line:
                continue

            # Check if stone has empty space facing the center
            faces_center = False

            # From top edge (rows 1-5), check if space below is empty
            if 1 <= r <= 5:
                if r + 1 < 19 and board_rows[r + 1][c] == '.':
                    faces_center = True

            # From bottom edge (rows 13-17), check if space above is empty
