                    faces_center = True

            # From left edge (cols 1-5), check if space right is empty
            if 1 <= c <= 5:
                if c + 1 < 19 and board_rows[r][c + 1] == '.':
                    faces_center = True

            # From right edge (cols 13-17), check if space left is empty
            if 13 <= c <= 17:
                if c - 1 >= 0 and board_rows[r][c - 1] == '.':
                    faces_center = True

            if faces_center:
                if stone == color:
                    color_expansion += 1
                else:
                    opp_expansion += 1

    return color_expansion > opp_expansion

