MOTIF_NAME = 'effective_cutting_density_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has a higher density of effective cutting stones (cutting opponent with some freedom) than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_cuts = 0
    opp_cuts = 0
    color_stones = 0
    opp_stones = 0

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.':
                continue

            is_color = (stone == color)
            if is_color:
                color_stones += 1
            else:
                opp_stones += 1

            # Check for freedom (liberty or connection to same color)
            has_freedom = False
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    n = board_rows[nr][nc]
                    if n == '.' or n == stone:
                        has_freedom = True
                        break

            # If completely surrounded by opponent, it's likely dead/ineffective.
            if not has_freedom:
                continue

            # Check for cutting (opponent on opposite orthogonal sides)
            is_cut = False
            # Vertical cut
            if r > 0 and r < 18:
                n_up = board_rows[r-1][c]
                n_down = board_rows[r+1][c]
                if is_color:
                    if n_up == opp and n_down == opp:
                        is_cut = True
                else:
                    if n_up == color and n_down == color:
                        is_cut = True
            # Horizontal cut
            if c > 0 and c < 18:
                n_left = board_rows[r][c-1]
                n_right = board_rows[r][c+1]
                if is_color:
                    if n_left == opp and n_right == opp:
                        is_cut = True
                else:
                    if n_left == color and n_right == color:
                        is_cut = True

            if is_cut:
                if is_color:
                    color_cuts += 1
                else:
                    opp_cuts += 1

    if color_stones == 0:
        return False
    if opp_stones == 0:
        return color_cuts > 0

    return color_cuts * opp_stones > opp_cuts * color_stones

