MOTIF_NAME = 'edge_support_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones on the first two lines that have same-color support on the third line, indicating stable edge presence.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_support = 0
    opp_support = 0

    # Check stones on first two lines (rows 0-1 and 17-18)
    edge_rows = [0, 1, 17, 18]
    third_line_rows = {0: 2, 1: 2, 17: 16, 18: 16}

    for r in edge_rows:
        for c in range(19):
            stone = board_rows[r][c]
            if stone not in ('B', 'W'):
                continue

            # Check if there is same-color support on the third line
            support_r = third_line_rows[r]
            has_support = False

            # Check vertically adjacent position on third line
            if 0 <= support_r < 19 and board_rows[support_r][c] == stone:
                has_support = True

            # Check diagonally adjacent positions on third line
            if not has_support:
                for dc in [-1, 1]:
                    nc = c + dc
                    if 0 <= nc < 19 and board_rows[support_r][nc] == stone:
                        has_support = True
                        break

            # Also check horizontal support on same edge line
            if not has_support:
                for dc in [-1, 1]:
                    nc = c + dc
                    if 0 <= nc < 19 and board_rows[r][nc] == stone:
                        has_support = True
                        break

            if has_support:
                if stone == color:
                    color_support += 1
                else:
                    opp_support += 1

    return color_support > opp_support

MOTIF_NAME = 'pair_connection_advantage'
MOTIF_DESCRIPTION = 'The evaluated color has more stones that are part of exactly 2-stone groups (pairs) than the opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    color_pairs = 0
    opp_pairs = 0

    def get_group(start_r, start_c, stone_color):
        group = set()
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in group:
                continue
            if board_rows[r][c] != stone_color:
                continue
            group.add((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    if board_rows[nr][nc] == stone_color:
                        stack.append((nr, nc))
        return group

    visited = set()
    for r in range(19):
        for c in range(19):
            if (r, c) in visited:
                continue
            stone = board_rows[r][c]
            if stone == '.':
                continue
            group = get_group(r, c, stone)
            visited.update(group)
            if len(group) == 2:
                if stone == color:
                    color_pairs += 2
                else:
                    opp_pairs += 2

    return color_pairs > opp_pairs

