                    is_hane = True
                if r + 1 < 19 and board_rows[r+1][c] == stone:
                    is_hane = True

            # Bottom-left diagonal has opponent, check right or up for own stone
            if r < 18 and c > 0 and board_rows[r+1][c-1] == opp:
                if c + 1 < 19 and board_rows[r][c+1] == stone:
                    is_hane = True
                if r - 1 >= 0 and board_rows[r-1][c] == stone:
                    is_hane = True

            # Bottom-right diagonal has opponent, check left or up for own stone
            if r < 18 and c < 18 and board_rows[r+1][c+1] == opp:
                if c - 1 >= 0 and board_rows[r][c-1] == stone:
                    is_hane = True
                if r - 1 >= 0 and board_rows[r-1][c] == stone:
                    is_hane = True

            if is_hane:
                if stone == color:
                    color_hanes += 1
                else:
                    opp_hanes += 1

    return color_hanes > opp_hanes
